  "bond.rex.0": "Don't touch me.",
  "bond.rex.1": "Not afraid, are you?",
  "bond.rex.2": "A little interesting.",
  "bond.rex.3": "Come to the next hunt too.",
  "bond.rex.4": "I've memorized your scent.",
  "bond.rex.5": "Don't leave my side.",
  "bond.rex.6": "Anything that comes for you, I bite.",
  "bond.rex.7": "You're late again today.",
  "bond.rex.8": "I prefer your voice to orders.",
  "bond.rex.9": "You are my only pack.",
  "bond.rex.10": "I will be on your side forever.",
  "bond.spino.0": "…What is it?",
  "bond.spino.1": "I miss the water.",
  "bond.spino.2": "It's fine to stay quiet.",
  "bond.spino.3": "Tell me more of your story.",
  "bond.spino.4": "The waves are calm today.",
  "bond.spino.5": "I like walking together.",
  "bond.spino.6": "If it's dangerous, get behind me.",
  "bond.spino.7": "I knew you would come.",
  "bond.spino.8": "I'm used to this city now.",
  "bond.spino.9": "Your side is my water.",
  "bond.spino.10": "Let's flow anywhere together.",
  "bond.generic.0": "It's still a little unfamiliar.",
  "bond.generic.1": "We met again today.",
  "bond.generic.2": "I'm getting used to it, bit by bit.",
  "bond.generic.3": "Let's go on a mission together.",
  "bond.generic.4": "I'm glad when you come.",
  "bond.generic.5": "You can stay beside me.",
  "bond.generic.6": "I'll help again this time.",
  "bond.generic.7": "I was waiting.",
  "bond.generic.8": "We're good companions.",
  "bond.generic.9": "I want to stay together a long time.",
  "bond.generic.10": "I'm counting on you from here on.",
