  "relic.raitia-grass.name": "Viria",
  "relic.raitia-grass.origin": "Dormouse",
  "relic.raitia-grass.excavationSite": "Slovenian Karst Cave Sediment",
  "relic.raitia-grass.fossilRecord": "Dozens of skulls of the same species were recovered from a single layer of cave sediment. Five of them match so closely in size and dentition that they were classified as one litter.",
  "relic.raitia-grass.catalogSummary": "A dormouse-based specimen restored with oversized incisors and cheek pouches.",
  "relic.raitia-grass.squadNote": "Annihilation's expendable mass. They flow all at once in whatever direction they are pointed and fill the corridor, the ones behind stepping straight over where the ones ahead fell.",
  "relic.raitia-grass.researcherTitle": "Researcher",
  "relic.raitia-grass.unlockRecord": "Identification Record 207. Confirmed as belonging to Annihilation. One of five in hooded pajamas with mouse ears, this one wears a green knot; a cheese-shaped pouch, toothed slippers, and a striped tail with a ribbon at the tip stand out. When it found food it signaled not with a cry but with the sound of its incisors, and the sisters that heard it swarmed to the same spot at once. Fresh shoots were left scattered where it gnawed, and seeds sprouted in every footprint along its path, leaving a green trail. Why it does not stop eating even when the season for hibernation arrives has not been confirmed.",
  "relic.raitia-grass.observation.originYear": "About 2 million years ago",
  "relic.raitia-grass.observation.restorationYear": "E.C. 2",
  "relic.raitia-grass.observation.lifeStage": "Juvenile",
  "relic.raitia-grass.observation.height": "0.94 m",
  "relic.raitia-grass.observation.weight": "21 kg",
  "relic.raitia-grass.passive.name": "Hibernation",
  "relic.raitia-grass.passive.desc": "Once per battle, when health drops to half or below, restores 3% of max health each second for 5 seconds.",
  "relic.raitia-grass.ferocity.name": "Gorging",
  "relic.raitia-grass.basic.name": "Incisor Gnaw",
  "relic.raitia-grass.ultimate.name": "Cheek Pouch Dump",
  "relic.raitia-grass.projectName": "ANNIHILATION SWARM — Overfed Population",
  "relic.raitia-water.name": "Guttia",
  "relic.raitia-water.origin": "Dormouse",
  "relic.raitia-water.excavationSite": "Slovenian Karst Cave Sediment",
  "relic.raitia-water.fossilRecord": "Dozens of skulls of the same species were recovered from a single layer of cave sediment. Five of them match so closely in size and dentition that they were classified as one litter.",
  "relic.raitia-water.catalogSummary": "A dormouse-based specimen restored with oversized incisors and cheek pouches.",
  "relic.raitia-water.squadNote": "Annihilation's expendable mass. They flow all at once in whatever direction they are pointed and fill the corridor, the ones behind stepping straight over where the ones ahead fell.",
  "relic.raitia-water.researcherTitle": "Researcher",
  "relic.raitia-water.unlockRecord": "Identification Record 208. Confirmed as belonging to Annihilation. One of the same hooded pajamas, this one has a blue-striped tail with a cotton ball at the tip, and smiles with one hand on its hip and the other fingers at the corner of its mouth. When it heard a sister's incisor sound it ran out first, smiling, and once close it gnawed whichever equipment was within reach with its incisors. Wet footprints trailed long behind where the pack had passed. What wets those footprints has not been confirmed.",
  "relic.raitia-water.observation.originYear": "About 2 million years ago",
  "relic.raitia-water.observation.restorationYear": "E.C. 2",
  "relic.raitia-water.observation.lifeStage": "Juvenile",
  "relic.raitia-water.observation.height": "0.94 m",
  "relic.raitia-water.observation.weight": "21 kg",
  "relic.raitia-water.passive.name": "Hibernation",
  "relic.raitia-water.passive.desc": "Once per battle, when health drops to half or below, restores 3% of max health each second for 5 seconds.",
  "relic.raitia-water.ferocity.name": "Gorging",
  "relic.raitia-water.basic.name": "Incisor Gnaw",
  "relic.raitia-water.ultimate.name": "Cheek Pouch Dump",
  "relic.raitia-water.projectName": "ANNIHILATION SWARM — Overfed Population",
  "relic.raitia-fire.name": "Favia",
  "relic.raitia-fire.origin": "Dormouse",
  "relic.raitia-fire.excavationSite": "Slovenian Karst Cave Sediment",
  "relic.raitia-fire.fossilRecord": "Dozens of skulls of the same species were recovered from a single layer of cave sediment. Five of them match so closely in size and dentition that they were classified as one litter.",
  "relic.raitia-fire.catalogSummary": "A dormouse-based specimen restored with oversized incisors and cheek pouches.",
  "relic.raitia-fire.squadNote": "Annihilation's expendable mass. They flow all at once in whatever direction they are pointed and fill the corridor, the ones behind stepping straight over where the ones ahead fell.",
  "relic.raitia-fire.researcherTitle": "Researcher",
  "relic.raitia-fire.unlockRecord": "Identification Record 209. Confirmed as belonging to Annihilation. One of the same hooded pajamas, this one wears a pink checkered ribbon, and stands with a half-awake face, one hand rubbing its eyes and the other on its hip. Despite looking sleepy it did not stop eating, and kept gnawing with its incisors even after its cheek pouches were full. When its sisters rushed off, it followed behind, still rubbing its eyes. Whether the drowsiness is an act or real has not been confirmed.",
  "relic.raitia-fire.observation.originYear": "About 2 million years ago",
  "relic.raitia-fire.observation.restorationYear": "E.C. 2",
  "relic.raitia-fire.observation.lifeStage": "Juvenile",
