  "relic.raitia-fire.passive.desc": "Once per battle, when health drops to half or below, restores 3% of max health each second for 5 seconds.",
  "relic.raitia-fire.ferocity.name": "Gorging",
  "relic.raitia-fire.basic.name": "Incisor Gnaw",
  "relic.raitia-fire.ultimate.name": "Cheek Pouch Dump",
  "relic.raitia-fire.projectName": "ANNIHILATION SWARM — Overfed Population",
  "relic.raitia-earth.name": "Silia",
  "relic.raitia-earth.origin": "Dormouse",
  "relic.raitia-earth.excavationSite": "Slovenian Karst Cave Sediment",
  "relic.raitia-earth.fossilRecord": "Dozens of skulls of the same species were recovered from a single layer of cave sediment. Five of them match so closely in size and dentition that they were classified as one litter.",
  "relic.raitia-earth.catalogSummary": "A dormouse-based specimen restored with oversized incisors and cheek pouches.",
  "relic.raitia-earth.squadNote": "Annihilation's expendable mass. They flow all at once in whatever direction they are pointed and fill the corridor, the ones behind stepping straight over where the ones ahead fell.",
  "relic.raitia-earth.researcherTitle": "Researcher",
  "relic.raitia-earth.unlockRecord": "Identification Record 210. Confirmed as belonging to Annihilation. One of the same hooded pajamas, this one stands out with a brown base, a yellow knot, and braided hair, and carries a large tuft of fur at the tip of its tail. When it stood with its hands stretched forward, the sisters all flowed in the direction of its fingertips at once, and where the one in front fell, the one behind stepped straight over. Who decides the direction its fingertips point has not been confirmed.",
  "relic.raitia-earth.observation.originYear": "About 2 million years ago",
  "relic.raitia-earth.observation.restorationYear": "E.C. 2",
  "relic.raitia-earth.observation.lifeStage": "Juvenile",
  "relic.raitia-earth.observation.height": "0.94 m",
  "relic.raitia-earth.observation.weight": "21 kg",
  "relic.raitia-earth.passive.name": "Hibernation",
  "relic.raitia-earth.passive.desc": "Once per battle, when health drops to half or below, restores 3% of max health each second for 5 seconds.",
