  "relic.raitia-earth.basic.name": "Incisor Gnaw",
  "relic.raitia-earth.ultimate.name": "Cheek Pouch Dump",
  "relic.raitia-earth.projectName": "ANNIHILATION SWARM — Overfed Population",
  "relic.raitia-wind.name": "Ventia",
  "relic.raitia-wind.origin": "Dormouse",
  "relic.raitia-wind.excavationSite": "Slovenian Karst Cave Sediment",
  "relic.raitia-wind.fossilRecord": "Dozens of skulls of the same species were recovered from a single layer of cave sediment. Five of them match so closely in size and dentition that they were classified as one litter.",
  "relic.raitia-wind.catalogSummary": "A dormouse-based specimen restored with oversized incisors and cheek pouches.",
  "relic.raitia-wind.squadNote": "Annihilation's expendable mass. They flow all at once in whatever direction they are pointed and fill the corridor, the ones behind stepping straight over where the ones ahead fell.",
  "relic.raitia-wind.researcherTitle": "Researcher",
  "relic.raitia-wind.unlockRecord": "Identification record 211. Confirmed as belonging to Annihilation. This is the one among the sisters in the same hooded pajamas who wears a mint-colored ribbon; she stands with her arms crossed and her mouth shut tight. She followed only after her sisters had rushed toward the food, and reluctantly at that, yet once there she worked her incisors the longest. Not once has she been observed signaling anything with the sound of her incisors.",
  "relic.raitia-wind.observation.originYear": "About 2 million years ago",
  "relic.raitia-wind.observation.restorationYear": "E.C. 2",
  "relic.raitia-wind.observation.lifeStage": "Juvenile",
  "relic.raitia-wind.observation.height": "0.94 m",
